// DASH-010 — Top Websites by Unique Users
let StartTime = _startTime;
let EndTime = _endTime;
Application_BrowserWebRequests2
| where Timestamp between (StartTime .. EndTime)
| extend Website = iff(isnotempty(TabHost), tostring(TabHost), tostring(RequestHost))
| where isnotempty(Website)
| where tostring(_website) == "" or tostring(_website) == "All" or Website == tostring(_website)
| summarize ['#Users'] = dcount(ProcUser) by URL = Website
| top 10 by ['#Users'] desc

// DASH-010 — Top Websites by Unique Hosts
let StartTime = _startTime;
let EndTime = _endTime;
Application_BrowserWebRequests2
| where Timestamp between (StartTime .. EndTime)
| extend Website = iff(isnotempty(TabHost), tostring(TabHost), tostring(RequestHost))
| where isnotempty(Website)
| where tostring(_website) == "" or tostring(_website) == "All" or Website == tostring(_website)
| summarize ['#Hosts'] = dcount(Host) by URL = Website
| top 10 by ['#Hosts'] desc

// DASH-010 — Request Count Over Time
let StartTime = _startTime;
let EndTime = _endTime;
let TimeBin = 1h;
let GroupByMode = "Tab host";
let GroupByValueFilter = iff(tostring(_website) == "All", "", tostring(_website));
let ParentGroupByMode = "Tab host";
let ParentGroupValue = iff(tostring(_website) == "All", "", tostring(_website));
let DurationMetric = "Page load total";
let RequestTypeFilter = tostring(_requestType);
let IncludeFrames = false;
Application_BrowserWebRequests2
| where Timestamp between (StartTime .. EndTime)
| extend RequestTypeName = case(
    RequestType == 1, "XmlHttpRequest",
    RequestType == 2, "WebSocket",
    RequestType == 3, "PageLoad",
    strcat("Unknown(", tostring(RequestType), ")")
)
| where
    isempty(RequestTypeFilter)
    or RequestTypeFilter == "All"
    or RequestTypeName == RequestTypeFilter
| where IncludeFrames or IsFrame == false
| extend GroupByValue = case(
    GroupByMode == "Browser", tostring(Browser),
    GroupByMode == "Browser version", tostring(BrowserVersion),
    GroupByMode == "User", tostring(ProcUser),
    GroupByMode == "Request host", tostring(RequestHost),
    GroupByMode == "Host", tostring(Host),
    tostring(TabHost)
)
| where isnotempty(GroupByValue)
| where
    isempty(GroupByValueFilter)
    or GroupByValue == GroupByValueFilter
| summarize ['Request count'] = sum(RequestCount)
    by
        TimeBucket = bin(Timestamp, TimeBin),
        GroupByValue
| order by TimeBucket asc, GroupByValue asc

// DASH-010 — Active Tab Foreground Percentage
let StartTime = _startTime;
let EndTime = _endTime;
let TimeBin = 1h;
let SelectedWebsite = iff(tostring(_website) == "All", "", tostring(_website));
let Counts =
    Session_SessionDetail
    | where Timestamp between (StartTime .. EndTime)
    | extend BrowserTab = iff(
        isempty(SessionFgBrowserActiveTabHost),
        "(none)",
        SessionFgBrowserActiveTabHost
    )
    | where isempty(SelectedWebsite) or BrowserTab == SelectedWebsite
    | summarize BrowserTabEvents = count()
        by
            TimeBucket = bin(Timestamp, TimeBin),
            BrowserTab;
let Totals =
    Counts
    | summarize TotalEvents = sum(BrowserTabEvents)
        by TimeBucket;
Counts
| join kind=inner Totals on TimeBucket
| extend ForegroundPercent = iff(
    TotalEvents > 0,
    round(
        100.0 * BrowserTabEvents / TotalEvents,
        1
    ),
    real(null)
)
| project TimeBucket, BrowserTab, ForegroundPercent
| order by TimeBucket asc, BrowserTab asc

// DASH-010 — Top Browser Tabs by Foreground Time
let StartTime = _startTime;
let EndTime = _endTime;
let SelectedWebsite = iff(tostring(_website) == "All", "", tostring(_website));
let Counts =
    Session_SessionDetail
    | where Timestamp between (StartTime .. EndTime)
    | where isnotempty(SessionFgBrowserActiveTabHost)
    | where isempty(SelectedWebsite) or SessionFgBrowserActiveTabHost == SelectedWebsite
    | summarize TabEventCount = count()
        by BrowserTab = SessionFgBrowserActiveTabHost;
let TotalBrowserEvents =
    toscalar(Counts | summarize sum(TabEventCount));
Counts
| extend ['Relative time in foreground (%)'] = iff(
    TotalBrowserEvents > 0,
    round(
        100.0 * TabEventCount / TotalBrowserEvents,
        1
    ),
    real(null)
)
| top 10 by ['Relative time in foreground (%)'] desc
| project BrowserTab, ['Relative time in foreground (%)']

// DASH-010 — Foreground Share by Browser Type
let StartTime = _startTime;
let EndTime = _endTime;
let TimeBin = 1h;
let SelectedWebsite = iff(tostring(_website) == "All", "", tostring(_website));
let Counts =
    Session_SessionDetail
    | where Timestamp between (StartTime .. EndTime)
    | where isempty(SelectedWebsite) or SessionFgBrowserActiveTabHost == SelectedWebsite
    | extend BrowserType = case(
        isnull(SessionFgBrowserType), "(none)",
        SessionFgBrowserType == 1, "Chrome",
        SessionFgBrowserType == 2, "Internet Explorer",
        SessionFgBrowserType == 3, "Firefox",
        SessionFgBrowserType == 4, "Edge",
        strcat("Browser type ", tostring(SessionFgBrowserType))
    )
    | summarize BrowserEvents = count()
        by
            TimeBucket = bin(Timestamp, TimeBin),
            BrowserType;
let Totals =
    Counts
    | summarize TotalEvents = sum(BrowserEvents)
        by TimeBucket;
Counts
| join kind=inner Totals on TimeBucket
| extend ForegroundPercent = iff(
    TotalEvents > 0,
    round(
        100.0 * BrowserEvents / TotalEvents,
        1
    ),
    real(null)
)
| project TimeBucket, BrowserType, ForegroundPercent
| order by TimeBucket asc, BrowserType asc
